/**
 * This file is part of the PimBay Asset Dedup service.
 *
 * @author Jan Sarmir <sarmir@pimbay.dev>
 * @link   https://pimbay.dev
 *
 * For the full license information, see the LICENSE file.
 */
import { and, eq, gte, lt, or, sql } from 'drizzle-orm';
import { alias } from 'drizzle-orm/pg-core';
import type { DbClient } from '../client.js';
import { assetHashDuplicateTable, assetTable } from '../schema.js';
import type {
  AssetHashDuplicates,
  AssetHashDuplicateEdge,
  AssetHashDuplicateMatch,
} from '../../../domain/repo/asset.repo.js';
import { Identity } from '../../../domain/model/asset.model.js';
import type { ClusterWriter } from '../../../application/writer/cluster.writer.js';
import type { AssetHashDuplicateWriter } from '../../../application/writer/asset.writer.js';
import { identityCondition } from './asset.repository.js';

export class DrizzleAssetHashDuplicateRepository implements AssetHashDuplicates, AssetHashDuplicateWriter {
  /** `clusterWriter` is the one place this repository reaches into another's territory — every write below
   * must invalidate the cluster cache, but owning `cluster_generation` belongs to `DrizzleClusterRepository`. */
  constructor(
    private readonly db: DbClient,
    private readonly clusterWriter: ClusterWriter,
  ) {}

  /** One upserted row per matching asset per direction, written together (symmetric distance/similarity)
   * — lets every read join/group on `asset_id` alone, no UNION. */
  async recomputeExact(projectId: string, algorithmId: number, assetId: string): Promise<void> {
    await this.db.execute(sql`
      WITH new_hashes AS (
        SELECT hash FROM asset_hash WHERE asset_id = ${assetId} AND algorithm_id = ${algorithmId}
      ),
      matches AS (
        SELECT DISTINCT ah.asset_id AS other_asset_id
        FROM asset_hash ah
        JOIN asset a ON a.id = ah.asset_id
        JOIN new_hashes nh ON nh.hash = ah.hash
        WHERE a.project_id = ${projectId} AND ah.algorithm_id = ${algorithmId} AND ah.asset_id <> ${assetId}
      )
      INSERT INTO asset_hash_duplicate (algorithm_id, asset_id, other_asset_id, distance, similarity, computed_at)
      SELECT ${algorithmId}::integer, ${assetId}::uuid, other_asset_id, 0, 100, now() FROM matches
      UNION ALL
      SELECT ${algorithmId}::integer, other_asset_id, ${assetId}::uuid, 0, 100, now() FROM matches
      ON CONFLICT (algorithm_id, asset_id, other_asset_id)
      DO UPDATE SET distance = 0, similarity = 100, computed_at = EXCLUDED.computed_at
    `);

    await this.clusterWriter.bumpGeneration(projectId, algorithmId);
  }

  /** Hamming distance via bit_count()/XOR (PG14+); both directions written together, see {@link recomputeExact}. */
  async recomputeHamming(
    projectId: string,
    algorithmId: number,
    assetId: string,
    minSimilarity: number,
  ): Promise<void> {
    await this.db.execute(sql`
      WITH new_hashes AS (
        SELECT hash FROM asset_hash WHERE asset_id = ${assetId} AND algorithm_id = ${algorithmId}
      ),
      candidate_distances AS (
        SELECT ah.asset_id AS other_asset_id,
               length(nh.hash) * 4 AS bit_length,
               bit_count(('x' || nh.hash)::bit varying # ('x' || ah.hash)::bit varying) AS distance
        FROM asset_hash ah
        JOIN asset a ON a.id = ah.asset_id
        CROSS JOIN new_hashes nh
        WHERE a.project_id = ${projectId} AND ah.algorithm_id = ${algorithmId} AND ah.asset_id <> ${assetId}
      ),
      best AS (
        SELECT other_asset_id, MIN(distance) AS distance, MAX(bit_length) AS bit_length
        FROM candidate_distances
        GROUP BY other_asset_id
      ),
      scored AS (
        SELECT other_asset_id, distance, round((bit_length - distance)::numeric / bit_length * 100, 1) AS similarity
        FROM best
      ),
      qualifying AS (
        SELECT * FROM scored WHERE similarity >= ${minSimilarity}
      )
      INSERT INTO asset_hash_duplicate (algorithm_id, asset_id, other_asset_id, distance, similarity, computed_at)
      SELECT ${algorithmId}::integer, ${assetId}::uuid, other_asset_id, distance, similarity, now() FROM qualifying
      UNION ALL
      SELECT ${algorithmId}::integer, other_asset_id, ${assetId}::uuid, distance, similarity, now() FROM qualifying
      ON CONFLICT (algorithm_id, asset_id, other_asset_id)
      DO UPDATE SET distance = EXCLUDED.distance, similarity = EXCLUDED.similarity, computed_at = EXCLUDED.computed_at
    `);

    await this.clusterWriter.bumpGeneration(projectId, algorithmId);
  }

  /** Both directional rows reference `assetId`. Must run while its `asset` row still exists (see
   * {@link bumpGenerationForAsset}) — every current call site already calls this before removing the
   * asset, so this just makes that a hard requirement rather than an accident of call order. */
  async deleteByAsset(algorithmId: number, assetId: string): Promise<void> {
    await this.db
      .delete(assetHashDuplicateTable)
      .where(
        and(
          eq(assetHashDuplicateTable.algorithmId, algorithmId),
          or(eq(assetHashDuplicateTable.assetId, assetId), eq(assetHashDuplicateTable.otherAssetId, assetId)),
        ),
      );

    await this.clusterWriter.bumpGenerationForAsset(algorithmId, assetId);
  }

  /** Every row's own `asset_id` is in-project (matches never cross projects), so this alone is sufficient. */
  async deleteByProject(projectId: string, algorithmId: number): Promise<void> {
    await this.db.execute(sql`
      DELETE FROM asset_hash_duplicate d
      USING asset a
      WHERE a.id = d.asset_id AND a.project_id = ${projectId} AND d.algorithm_id = ${algorithmId}
    `);

    await this.clusterWriter.bumpGeneration(projectId, algorithmId);
  }

  /** Each edge is stored as two directional rows; `asset_id < other_asset_id` keeps this at one row per edge. */
  async findByProject(
    projectId: string,
    algorithmId: number,
    minSimilarity: number,
  ): Promise<AssetHashDuplicateEdge[]> {
    const assetA = alias(assetTable, 'asset_a');
    const assetB = alias(assetTable, 'asset_b');

    const rows = await this.db
      .select({
        aId: assetA.identityId,
        aPath: assetA.identityPath,
        bId: assetB.identityId,
        bPath: assetB.identityPath,
        distance: assetHashDuplicateTable.distance,
        similarity: assetHashDuplicateTable.similarity,
      })
      .from(assetHashDuplicateTable)
      .innerJoin(assetA, eq(assetA.id, assetHashDuplicateTable.assetId))
      .innerJoin(assetB, eq(assetB.id, assetHashDuplicateTable.otherAssetId))
      .where(
        and(
          eq(assetA.projectId, projectId),
          eq(assetHashDuplicateTable.algorithmId, algorithmId),
          gte(assetHashDuplicateTable.similarity, minSimilarity),
          lt(assetHashDuplicateTable.assetId, assetHashDuplicateTable.otherAssetId),
        ),
      );

    return rows.map((row) => ({
      identityA: new Identity(row.aId, row.aPath),
      identityB: new Identity(row.bId, row.bPath),
      distance: row.distance,
      similarity: row.similarity,
    }));
  }

  /** Batched lookup for one or more assets — no UNION, the requested asset is always the row's own `asset_id`. */
  async findByAssets(
    projectId: string,
    identities: Identity[],
    algorithmId: number,
    minSimilarity: number,
  ): Promise<AssetHashDuplicateMatch[]> {
    // Stryker disable next-line all: pure optimization, not correctness — `or()` on an empty array below
    // returns `undefined`, which would drop the filter entirely (matching everything) rather than nothing,
    // so this guard is also a correctness guard, not just a saved round-trip.
    if (identities.length === 0) {
      return [];
    }

    const self = alias(assetTable, 'asset_self');
    const other = alias(assetTable, 'asset_other');

    const rows = await this.db
      .select({
        selfId: self.identityId,
        selfPath: self.identityPath,
        otherId: other.identityId,
        otherPath: other.identityPath,
        distance: assetHashDuplicateTable.distance,
        similarity: assetHashDuplicateTable.similarity,
      })
      .from(assetHashDuplicateTable)
      .innerJoin(self, eq(self.id, assetHashDuplicateTable.assetId))
      .innerJoin(other, eq(other.id, assetHashDuplicateTable.otherAssetId))
      .where(
        and(
          eq(self.projectId, projectId),
          eq(assetHashDuplicateTable.algorithmId, algorithmId),
          gte(assetHashDuplicateTable.similarity, minSimilarity),
          or(...identities.map((identity) => identityCondition(self, identity))),
        ),
      );

    return rows.map((row) => ({
      identity: new Identity(row.selfId, row.selfPath),
      otherIdentity: new Identity(row.otherId, row.otherPath),
      distance: row.distance,
      similarity: row.similarity,
    }));
  }

  /** Same dedup filter as `findByProject` — counts each directional pair once. */
  async countPairsByProject(projectId: string): Promise<number> {
    const [row] = await this.db
      .select({ value: sql<number>`count(*)::int`.as('value') })
      .from(assetHashDuplicateTable)
      .innerJoin(assetTable, eq(assetTable.id, assetHashDuplicateTable.assetId))
      .where(
        and(
          eq(assetTable.projectId, projectId),
          lt(assetHashDuplicateTable.assetId, assetHashDuplicateTable.otherAssetId),
        ),
      );

    /* v8 ignore next -- unreachable: COUNT(*) with no GROUP BY always returns exactly one row */
    return row?.value ?? 0;
  }
}

/**
 * This file is part of the PimBay Asset Dedup service.
 *
 * @author Jan Sarmir <sarmir@pimbay.dev>
 * @link   https://pimbay.dev
 *
 * For the full license information, see the LICENSE file.
 */
import { and, eq, gte, sql, type SQL } from 'drizzle-orm';
import { alias } from 'drizzle-orm/pg-core';
import type { DbClient } from '../client.js';
import { assetHashDuplicateTable, assetTable } from '../schema.js';
import type { PageAdapter, Page } from '@pimbay/search-query';
import { paginatePage, mapPage, createSearchTermsConfig } from '@pimbay/search-query';
import { DrizzleSimpleAdapter, buildSearchTermsConditionFromString } from '@pimbay/search-query-drizzle';
import type { AssetHashDuplicates } from '../../../domain/repo/asset.repo.js';
import { Identity } from '../../../domain/model/asset.model.js';
import { identityCondition } from './asset.repository.js';
import type {
  AssetHashDuplicatesSearch,
  AssetHashDuplicateRankingQuery,
  AssetHashDuplicateMatchesQuery,
  AssetHashDuplicateCount,
  AssetWithDuplicateCount,
  DuplicateMatch,
} from '../../../application/query/asset.query.js';

/** Raw SELECT shape for the ranking query — `identityId`/`identityPath` are assembled into an `Identity`
 * right after paginating, same split as `RawDuplicateMatchRow` below. */
interface RawDuplicateCountRow {
  identityId: string | null;
  identityPath: string | null;
  duplicateCount: number;
}

interface RawDuplicateMatchRow {
  identityId: string | null;
  identityPath: string | null;
  distance: number;
  similarity: number;
}

function toDuplicateCount(row: RawDuplicateCountRow): AssetHashDuplicateCount {
  return { identity: new Identity(row.identityId, row.identityPath), duplicateCount: row.duplicateCount };
}

function toDuplicateMatch(row: RawDuplicateMatchRow): DuplicateMatch {
  return {
    identity: new Identity(row.identityId, row.identityPath),
    distance: row.distance,
    similarity: row.similarity,
  };
}

/** Map key for grouping by an asset's identity in-memory — both fields together, since either alone could
 * collide with a different asset that only has the other field set (e.g. `id=null,path='x'` vs
 * `id='x',path=null`). Not a lookup condition, just a stable key for `Map`. */
function identityKey(identity: Identity): string {
  // Stryker disable next-line StringLiteral: the exact fallback text on either side is never observable — it
  // only has to be *consistent* between the write and read side of the map, and the DB's own unique indexes
  // on `(project, identity_id)`/`(project, identity_path)` mean two distinct real assets can never share the
  // field that's present, so no legitimate test data can make the fallback text matter.
  return `${identity.id ?? ''}\u0000${identity.path ?? ''}`;
}

export class DrizzleAssetHashDuplicateSearchRepository implements AssetHashDuplicatesSearch {
  constructor(
    private readonly db: DbClient,
    private readonly assetHashDuplicates: AssetHashDuplicates,
  ) {}

  async paginateRanking(
    query: AssetHashDuplicateRankingQuery,
    page: number,
    size: number,
  ): Promise<Page<AssetWithDuplicateCount>> {
    const rawRanked = await paginatePage(this.getRankingAdapter(query), page, size);
    const ranked = mapPage(rawRanked, toDuplicateCount);
    const matchesByAsset = await this.loadMatches(query, ranked.getData());

    return mapPage(ranked, (row) => withMatches(row, matchesByAsset, query.matchLimit));
  }

  private getRankingAdapter(query: AssetHashDuplicateRankingQuery): PageAdapter<RawDuplicateCountRow> {
    return createRankingAdapter(this.db, query);
  }

  async paginateMatches(
    query: AssetHashDuplicateMatchesQuery,
    page: number,
    size: number,
  ): Promise<Page<DuplicateMatch>> {
    const raw = await paginatePage(createMatchesAdapter(this.db, query), page, size);

    return mapPage(raw, toDuplicateMatch);
  }

  private async loadMatches(
    query: AssetHashDuplicateRankingQuery,
    ranked: readonly AssetHashDuplicateCount[],
  ): Promise<Map<string, DuplicateMatch[]>> {
    const matchesByAsset = new Map<string, DuplicateMatch[]>();

    if (ranked.length === 0) {
      return matchesByAsset;
    }

    const matchRows = await this.assetHashDuplicates.findByAssets(
      query.projectId,
      ranked.map((row) => row.identity),
      query.algorithmId,
      query.minSimilarity,
    );

    matchRows.forEach((row) => {
      const key = identityKey(row.identity);
      const list = matchesByAsset.get(key) ?? [];
      list.push({ identity: row.otherIdentity, distance: row.distance, similarity: row.similarity });
      matchesByAsset.set(key, list);
    });

    return matchesByAsset;
  }
}

const SEARCH_TERMS_CONFIG = createSearchTermsConfig({ anywhere: true });

/** Directional storage means count/ranking share the same FROM/JOIN — no UNION needed. Groups by `asset.id`
 * (the PK) rather than the identity columns directly — Postgres' functional-dependency rule then allows
 * selecting `identity_id`/`identity_path` ungrouped, correct regardless of which field is set. Exported so
 * `head()`/`all()` (unused by `paginatePage()`) can be tested directly. */
export function createRankingAdapter(
  db: DbClient,
  query: AssetHashDuplicateRankingQuery,
): DrizzleSimpleAdapter<{ count: number }, RawDuplicateCountRow> {
  const scope: SQL | undefined = and(
    eq(assetTable.projectId, query.projectId),
    eq(assetHashDuplicateTable.algorithmId, query.algorithmId),
    gte(assetHashDuplicateTable.similarity, query.minSimilarity),
    query.id === undefined ? undefined : eq(assetTable.identityId, query.id),
    query.path === undefined
      ? undefined
      : buildSearchTermsConditionFromString(assetTable.identityPath, query.path, SEARCH_TERMS_CONFIG),
  );

  return new DrizzleSimpleAdapter(
    () =>
      db
        .select({ count: sql<number>`count(distinct ${assetTable.id})::int`.as('count') })
        .from(assetHashDuplicateTable)
        .innerJoin(assetTable, eq(assetTable.id, assetHashDuplicateTable.assetId))
        .$dynamic()
        .where(scope),
    (row) => row.count,
    () =>
      db
        .select({
          identityId: assetTable.identityId,
          identityPath: assetTable.identityPath,
          duplicateCount: sql<number>`count(*)::int`.as('duplicate_count'),
        })
        .from(assetHashDuplicateTable)
        .innerJoin(assetTable, eq(assetTable.id, assetHashDuplicateTable.assetId))
        .$dynamic()
        .where(scope)
        .groupBy(assetTable.id)
        .orderBy(sql`duplicate_count desc`, assetTable.identityId, assetTable.identityPath),
  );
}

/** Pure, sync — the batched match lookup already happened; this only assembles + sorts + caps. */
function withMatches(
  ranked: AssetHashDuplicateCount,
  matchesByAsset: Map<string, DuplicateMatch[]>,
  matchLimit: number | undefined,
): AssetWithDuplicateCount {
  /* v8 ignore next -- unreachable: findByAssets uses the same minSimilarity filter as the ranking
     query, so every asset here (duplicateCount > 0) always has >=1 entry in matchesByAsset */
  const matches = (matchesByAsset.get(identityKey(ranked.identity)) ?? []).sort((a, b) => b.similarity - a.similarity);
  // Stryker disable next-line ConditionalExpression: `.slice(0, undefined)` returns the whole array per JS
  // spec, identical to not slicing at all — so this guard is unobservable when matchLimit is undefined;
  // `caps matches per asset at matchLimit` already covers the defined case.
  const limited = matchLimit !== undefined ? matches.slice(0, matchLimit) : matches;

  return {
    identity: ranked.identity,
    duplicateCount: ranked.duplicateCount,
    matches: limited,
  };
}

export function createMatchesAdapter(
  db: DbClient,
  query: AssetHashDuplicateMatchesQuery,
): DrizzleSimpleAdapter<{ count: number }, RawDuplicateMatchRow> {
  const self = alias(assetTable, 'asset_self');
  const other = alias(assetTable, 'asset_other');
  const scope: SQL | undefined = and(
    eq(self.projectId, query.projectId),
    identityCondition(self, query.identity),
    eq(assetHashDuplicateTable.algorithmId, query.algorithmId),
    gte(assetHashDuplicateTable.similarity, query.minSimilarity),
  );

  return new DrizzleSimpleAdapter(
    () =>
      db
        .select({ count: sql<number>`count(*)::int`.as('count') })
        .from(assetHashDuplicateTable)
        .innerJoin(self, eq(self.id, assetHashDuplicateTable.assetId))
        .innerJoin(other, eq(other.id, assetHashDuplicateTable.otherAssetId))
        .$dynamic()
        .where(scope),
    (row) => row.count,
    () =>
      db
        .select({
          identityId: other.identityId,
          identityPath: other.identityPath,
          distance: assetHashDuplicateTable.distance,
          similarity: assetHashDuplicateTable.similarity,
        })
        .from(assetHashDuplicateTable)
        .innerJoin(self, eq(self.id, assetHashDuplicateTable.assetId))
        .innerJoin(other, eq(other.id, assetHashDuplicateTable.otherAssetId))
        .$dynamic()
        .where(scope)
        .orderBy(sql`similarity desc`),
  );
}

/**
 * This file is part of the PimBay Asset Dedup service.
 *
 * @author Jan Sarmir <sarmir@pimbay.dev>
 * @link   https://pimbay.dev
 *
 * For the full license information, see the LICENSE file.
 */
import { and, eq, gt, sql } from 'drizzle-orm';
import type { SQL } from 'drizzle-orm';
import type { PgColumn } from 'drizzle-orm/pg-core';
import type { DbClient, DbOrTx } from '../client.js';
import { assetTable, assetHashTable, algorithmTable } from '../schema.js';
import type { Assets, AssetCountPerRecipe, AssetActivitySummary } from '../../../domain/repo/asset.repo.js';
import type { Asset } from '../../../domain/model/model.js';
import { Identity } from '../../../domain/model/asset.model.js';
import type { AssetWriter, CreateAssetParams, CreateAssetResult } from '../../../application/writer/asset.writer.js';
import { NotFoundError, AlreadyExistsError } from '../../../domain/errors.js';

/** Any asset-shaped table/alias exposing the two identity columns — lets the same condition builder work
 * against `assetTable` directly or any of its joined aliases (`asset_a`, `asset_self`, ...). */
interface AssetIdentityColumns {
  identityId: PgColumn;
  identityPath: PgColumn;
}

/** `id` takes priority over `path` — see `Identity`'s doc comment for why a lookup only ever uses one. */
export function identityCondition(asset: AssetIdentityColumns, identity: Identity): SQL {
  if (identity.id !== null) {
    return eq(asset.identityId, identity.id);
  }

  // Stryker disable next-line ConditionalExpression: same reason as the v8 ignore below — forcing this to
  // `true` is unobservable, since every test that reaches this line already has a non-null `path` per the
  // invariant the v8 ignore explains.
  /* v8 ignore else -- unreachable: Identity's own constructor guarantees id and path are not both null,
   * so if id is null here, path is always non-null. */
  if (identity.path !== null) {
    return eq(asset.identityPath, identity.path);
  }

  // Stryker disable next-line all: unreachable in practice — guards the type narrowing above, not a code path any test can trigger honestly.
  /* v8 ignore next -- unreachable: Identity's own constructor guarantees id and path are not both null */
  throw new Error('unreachable: Identity with neither id nor path');
}

function isGiven(value: string | null): value is string {
  return value !== null && value !== '';
}

/** `null` (not sent) keeps `previous`; `""` (sent as empty) clears it; anything else replaces it.
 * Exported so the `""`-clears-to-`null` contract can be unit-tested directly — the only caller passes the
 * result straight into `new Identity(...)`, whose own constructor normalizes `""` to `null` too, so a black-box
 * test of `create()` alone can't distinguish this function returning `null` from it returning `""` unchanged. */
export function resolveField(raw: string | null, previous: string | null): string | null {
  if (raw === null) {
    return previous;
  }

  if (raw === '') {
    return null;
  }

  return raw;
}

export class DrizzleAssetRepository implements Assets, AssetWriter {
  constructor(private readonly db: DbClient) {}

  async findByIdentity(projectId: string, identity: Identity): Promise<Asset | null> {
    const [row] = await this.db
      .select()
      .from(assetTable)
      .where(and(eq(assetTable.projectId, projectId), identityCondition(assetTable, identity)))
      .limit(1);

    return row ?? null;
  }

  async getByIdentity(projectId: string, identity: Identity): Promise<Asset> {
    const asset = await this.findByIdentity(projectId, identity);

    if (asset === null) {
      throw NotFoundError.asset(identity);
    }

    return asset;
  }

  /** Locks the matching row (`SELECT ... FOR UPDATE`) so a concurrent `create` racing on the same identity
   * waits instead of both reading a stale "no previous row" and colliding on the unique index. */
  private async findLocked(tx: DbOrTx, projectId: string, condition: SQL): Promise<Asset | null> {
    const [row] = await tx
      .select()
      .from(assetTable)
      .where(and(eq(assetTable.projectId, projectId), condition))
      .for('update')
      .limit(1);

    return row ?? null;
  }

  /** Upsert: `id` takes priority over `path` when looking for a previous row to patch. If both are given
   * and match *different* existing rows, that's a genuine conflict (`AlreadyExistsError`), not something
   * priority order or a `null`/`""` rule can silently resolve. */
  async create(params: CreateAssetParams): Promise<CreateAssetResult> {
    return this.db.transaction(async (tx) => {
      const byId = isGiven(params.identityId)
        ? await this.findLocked(tx, params.projectId, eq(assetTable.identityId, params.identityId))
        : null;
      const byPath = isGiven(params.identityPath)
        ? await this.findLocked(tx, params.projectId, eq(assetTable.identityPath, params.identityPath))
        : null;

      if (byId !== null && byPath !== null && byId.id !== byPath.id) {
        throw AlreadyExistsError.asset(new Identity(params.identityId, params.identityPath));
      }

      const previous = byId ?? byPath;
      const identity = new Identity(
        resolveField(params.identityId, previous?.identityId ?? null),
        resolveField(params.identityPath, previous?.identityPath ?? null),
      );

      if (previous !== null) {
        const [row] = await tx
          .update(assetTable)
          .set({ identityId: identity.id, identityPath: identity.path, updatedAt: new Date() })
          .where(eq(assetTable.id, previous.id))
          .returning();

        /* v8 ignore next 3 -- unreachable: updating by the id of a row just selected in the same tx always returns exactly one row */
        if (row === undefined) {
          // Stryker disable next-line all: unreachable — see the v8 ignore above, same reasoning.
          throw new Error('asset update returned no rows');
        }

        return { id: row.id, identity };
      }

      const [row] = await tx
        .insert(assetTable)
        .values({ projectId: params.projectId, identityId: identity.id, identityPath: identity.path })
        .returning();

      /* v8 ignore next 3 -- unreachable: a successful INSERT always returns exactly one row */
      if (row === undefined) {
        // Stryker disable next-line all: unreachable — see the v8 ignore above, same reasoning.
        throw new Error('asset insert returned no rows');
      }

      return { id: row.id, identity };
    });
  }

  async deleteByIdentity(projectId: string, identity: Identity): Promise<void> {
    await this.db
      .delete(assetTable)
      .where(and(eq(assetTable.projectId, projectId), identityCondition(assetTable, identity)));
  }

  async listRecipes(projectId: string, identity: Identity): Promise<string[]> {
    const rows = await this.db
      .selectDistinct({ recipe: algorithmTable.recipe })
      .from(assetHashTable)
      .innerJoin(assetTable, eq(assetTable.id, assetHashTable.assetId))
      .innerJoin(algorithmTable, eq(algorithmTable.id, assetHashTable.algorithmId))
      .where(and(eq(assetTable.projectId, projectId), identityCondition(assetTable, identity)));

    return rows.map((row) => row.recipe);
  }

  async listIdsWithHash(
    projectId: string,
    algorithmId: number,
    afterId: string | null,
    limit: number,
  ): Promise<string[]> {
    const conditions = [eq(assetTable.projectId, projectId)];

    if (afterId !== null) {
      conditions.push(gt(assetTable.id, afterId));
    }

    const rows = await this.db
      .selectDistinct({ id: assetTable.id })
      .from(assetTable)
      .innerJoin(
        assetHashTable,
        and(eq(assetHashTable.assetId, assetTable.id), eq(assetHashTable.algorithmId, algorithmId)),
      )
      .where(and(...conditions))
      .orderBy(assetTable.id)
      .limit(limit);

    return rows.map((row) => row.id);
  }

  async countByProject(projectId: string): Promise<number> {
    const [row] = await this.db
      .select({ value: sql<number>`count(*)::int`.as('value') })
      .from(assetTable)
      .where(eq(assetTable.projectId, projectId));

    /* v8 ignore next -- unreachable: COUNT(*) with no GROUP BY always returns exactly one row */
    return row?.value ?? 0;
  }

  /** One row per recipe with a hash — unhashed recipes are absent, zero-filled by the caller. */
  async countPerRecipe(projectId: string): Promise<AssetCountPerRecipe[]> {
    const rows = await this.db
      .select({
        recipe: algorithmTable.recipe,
        assetCount: sql<number>`count(distinct ${assetHashTable.assetId})::int`.as('asset_count'),
      })
      .from(assetHashTable)
      .innerJoin(assetTable, eq(assetTable.id, assetHashTable.assetId))
      .innerJoin(algorithmTable, eq(algorithmTable.id, assetHashTable.algorithmId))
      .where(eq(assetTable.projectId, projectId))
      .groupBy(algorithmTable.recipe);

    return rows;
  }

  async getActivitySummary(projectId: string): Promise<AssetActivitySummary> {
    const [row] = await this.db
      .select({
        lastAddedAt: sql<string | null>`max(${assetTable.createdAt})`.as('last_added_at'),
        addedLast7d: sql<number>`count(*) filter (where ${assetTable.createdAt} >= now() - interval '7 days')::int`.as(
          'added_last_7d',
        ),
        addedLast30d:
          sql<number>`count(*) filter (where ${assetTable.createdAt} >= now() - interval '30 days')::int`.as(
            'added_last_30d',
          ),
      })
      .from(assetTable)
      .where(eq(assetTable.projectId, projectId));

    /* v8 ignore next 5 -- unreachable: COUNT(*)/MAX(*) with no GROUP BY always returns exactly one row */
    return {
      lastAddedAt: row?.lastAddedAt ? new Date(row.lastAddedAt) : null,
      addedLast7d: row?.addedLast7d ?? 0,
      addedLast30d: row?.addedLast30d ?? 0,
    };
  }
}

