import { describe, it, expect } from 'vitest';
import { sql } from 'drizzle-orm';
import {
  DrizzleClusterRepository,
  MAX_CLUSTER_EDGE_COUNT,
} from '../../../../../src/infrastructure/drizzle/repository/cluster.repository.js';
import { DrizzleAssetHashDuplicateRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.hashDuplicate.repository.js';
import { DrizzleAssetHashRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.hash.repository.js';
import type { DbClient } from '../../../../../src/infrastructure/drizzle/client.js';
import { useTestDb } from '../../../../helpers/db.js';
import { makeProject, makeAsset, makeAlgorithm } from '../../../../helpers/fixtures.js';
import { ValidationError } from '../../../../../src/domain/errors.js';
import type { Asset } from '../../../../../src/domain/model/model.js';

async function setup(db: DbClient): Promise<{
  projectId: string;
  algorithmId: number;
  clusters: DrizzleClusterRepository;
  duplicates: DrizzleAssetHashDuplicateRepository;
  hashes: DrizzleAssetHashRepository;
}> {
  const project = await makeProject(db);
  const algorithm = await makeAlgorithm(db);
  const clusters = new DrizzleClusterRepository(db);

  return {
    projectId: project.id,
    algorithmId: algorithm.id,
    clusters,
    duplicates: new DrizzleAssetHashDuplicateRepository(db, clusters),
    hashes: new DrizzleAssetHashRepository(db),
  };
}

/** Gives `a` and `b` a shared hash and recomputes both — an exact-comparison edge is always similarity 100. */
async function connect(
  hashes: DrizzleAssetHashRepository,
  duplicates: DrizzleAssetHashDuplicateRepository,
  projectId: string,
  algorithmId: number,
  a: Asset,
  b: Asset,
  sharedHash: string,
): Promise<void> {
  await hashes.replaceAll(a.id, algorithmId, [sharedHash]);
  await hashes.replaceAll(b.id, algorithmId, [sharedHash]);
  await duplicates.recomputeExact(projectId, algorithmId, a.id);
  await duplicates.recomputeExact(projectId, algorithmId, b.id);
}

describe('DrizzleClusterRepository', () => {
  const { db } = useTestDb();

  describe('countEdges', () => {
    it('returns 0 when there are no duplicate rows', async () => {
      const { clusters, projectId, algorithmId } = await setup(db());

      await expect(clusters.countEdges(projectId, algorithmId, 90)).resolves.toBe(0);
    });

    it('counts each undirected pair once', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');

      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared');

      await expect(clusters.countEdges(projectId, algorithmId, 90)).resolves.toBe(1);
    });

    it('excludes edges below the given similarity threshold', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');

      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared');

      // exact matches are always similarity=100, so a threshold above that excludes them
      await expect(clusters.countEdges(projectId, algorithmId, 100.1)).resolves.toBe(0);
    });
  });

  describe('bumpGeneration / bumpGenerationForAsset', () => {
    it('starts a scope at generation 1 on first bump', async () => {
      const { clusters, projectId, algorithmId } = await setup(db());

      await clusters.bumpGeneration(projectId, algorithmId);

      const { generation } = await clusters.ensureFresh(projectId, algorithmId, 90);
      expect(generation).toBe(1);
    });

    it('increments the generation on each subsequent bump', async () => {
      const { clusters, projectId, algorithmId } = await setup(db());

      await clusters.bumpGeneration(projectId, algorithmId);
      await clusters.bumpGeneration(projectId, algorithmId);
      await clusters.bumpGeneration(projectId, algorithmId);

      const { generation } = await clusters.ensureFresh(projectId, algorithmId, 90);
      expect(generation).toBe(3);
    });

    it('bumpGenerationForAsset resolves the project from the asset row and bumps the same scope', async () => {
      const { clusters, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');

      await clusters.bumpGenerationForAsset(algorithmId, a.id);

      const { generation } = await clusters.ensureFresh(projectId, algorithmId, 90);
      expect(generation).toBe(1);
    });

    it('bumpGenerationForAsset sweeps out cache entries past the retention window, keeping fresh ones', async () => {
      const { clusters, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');

      const stale = await clusters.ensureFresh(projectId, algorithmId, 90);
      const fresh = await clusters.ensureFresh(projectId, algorithmId, 95);
      await db().execute(
        sql`UPDATE cluster_cache_meta SET computed_at = now() - interval '2 hours' WHERE id = ${stale.metaId}`,
      );

      await clusters.bumpGenerationForAsset(algorithmId, a.id);

      const rows = await db().execute<{ id: number }>(
        sql`SELECT id FROM cluster_cache_meta WHERE project_id = ${projectId} AND algorithm_id = ${algorithmId}`,
      );
      const remainingIds = rows.map((r) => r.id);
      expect(remainingIds).not.toContain(stale.metaId);
      expect(remainingIds).toContain(fresh.metaId);
    });

    it('a write (recomputeExact) bumps the generation as a side effect', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');

      const before = await clusters.ensureFresh(projectId, algorithmId, 90);
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared');
      const after = await clusters.ensureFresh(projectId, algorithmId, 90);

      expect(after.generation).toBeGreaterThan(before.generation);
    });
  });

  describe('ensureFresh', () => {
    it('reuses the same cache entry (metaId) on repeat calls when nothing has changed', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared');

      const first = await clusters.ensureFresh(projectId, algorithmId, 90);
      const second = await clusters.ensureFresh(projectId, algorithmId, 90);

      expect(second.metaId).toBe(first.metaId);
      expect(second.generation).toBe(first.generation);
    });

    it('recomputes into a new cache entry after a write bumps the generation', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      const c = await makeAsset(db(), projectId, 'c');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared-ab');
      const first = await clusters.ensureFresh(projectId, algorithmId, 90);

      await connect(hashes, duplicates, projectId, algorithmId, b, c, 'shared-bc');
      const second = await clusters.ensureFresh(projectId, algorithmId, 90);

      expect(second.generation).toBeGreaterThan(first.generation);
      expect(second.metaId).not.toBe(first.metaId);
    });

    it('a different threshold for the same generation gets its own cache entry', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared');

      const at90 = await clusters.ensureFresh(projectId, algorithmId, 90);
      const at95 = await clusters.ensureFresh(projectId, algorithmId, 95);

      expect(at95.metaId).not.toBe(at90.metaId);
      expect(at95.generation).toBe(at90.generation);
    });

    it('reuses an existing cache entry when pinned to its generation', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared');
      const first = await clusters.ensureFresh(projectId, algorithmId, 90);

      const pinned = await clusters.ensureFresh(projectId, algorithmId, 90, first.generation);

      expect(pinned.metaId).toBe(first.metaId);
      expect(pinned.generation).toBe(first.generation);
    });

    it('throws ValidationError when pinned to a generation that was never computed', async () => {
      const { clusters, projectId, algorithmId } = await setup(db());

      await expect(clusters.ensureFresh(projectId, algorithmId, 90, 999)).rejects.toThrow(ValidationError);
      await expect(clusters.ensureFresh(projectId, algorithmId, 90, 999)).rejects.toThrow(/no longer available/);
    });
  });

  describe('computeStats', () => {
    it('returns zeroed stats when there are no qualifying edges', async () => {
      const { clusters, projectId, algorithmId } = await setup(db());

      await expect(clusters.computeStats(projectId, algorithmId, 90)).resolves.toEqual({
        clusterCount: 0,
        edgeCount: 0,
        assetsWithDuplicateCount: 0,
      });
    });

    it('groups two directly-connected assets into one cluster', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared');

      await expect(clusters.computeStats(projectId, algorithmId, 90)).resolves.toEqual({
        clusterCount: 1,
        edgeCount: 1,
        assetsWithDuplicateCount: 2,
      });
    });

    it('propagates cluster membership across more than one hop (A-B-C, no direct A-C edge)', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      const c = await makeAsset(db(), projectId, 'c');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared-ab');
      await connect(hashes, duplicates, projectId, algorithmId, b, c, 'shared-bc');

      const stats = await clusters.computeStats(projectId, algorithmId, 90);

      expect(stats?.clusterCount).toBe(1);
      expect(stats?.assetsWithDuplicateCount).toBe(3);
    });

    it('keeps two disconnected components as two separate clusters', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      const c = await makeAsset(db(), projectId, 'c');
      const d = await makeAsset(db(), projectId, 'd');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared-ab');
      await connect(hashes, duplicates, projectId, algorithmId, c, d, 'shared-cd');

      const stats = await clusters.computeStats(projectId, algorithmId, 90);

      expect(stats?.clusterCount).toBe(2);
      expect(stats?.assetsWithDuplicateCount).toBe(4);
    });

    it('does not count a singleton asset with no qualifying edge', async () => {
      const { clusters, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      await makeAsset(db(), projectId, 'lonely');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared');

      const stats = await clusters.computeStats(projectId, algorithmId, 90);

      expect(stats?.assetsWithDuplicateCount).toBe(2);
    });
  });

  describe('computeStats — over the edge-count safety cap', () => {
    it('returns null without attempting to compute clusters', async () => {
      const fakeDb = {
        execute: () => Promise.resolve([{ value: MAX_CLUSTER_EDGE_COUNT + 1 }]),
      } as unknown as DbClient;
      const clusters = new DrizzleClusterRepository(fakeDb);

      await expect(clusters.computeStats('project-1', 1, 90)).resolves.toBeNull();
    });
  });
});

import { describe, it, expect } from 'vitest';
import { DrizzleClusterRepository } from '../../../../../src/infrastructure/drizzle/repository/cluster.repository.js';
import { DrizzleClusterSearchRepository } from '../../../../../src/infrastructure/drizzle/repository/cluster.search.repository.js';
import { DrizzleAssetHashDuplicateRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.hashDuplicate.repository.js';
import { DrizzleAssetHashRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.hash.repository.js';
import { DrizzleAssetRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.repository.js';
import type { DbClient } from '../../../../../src/infrastructure/drizzle/client.js';
import type { Clusters } from '../../../../../src/domain/repo/cluster.repo.js';
import { useTestDb } from '../../../../helpers/db.js';
import { makeProject, makeAsset, makeAlgorithm } from '../../../../helpers/fixtures.js';
import { ValidationError } from '../../../../../src/domain/errors.js';
import type { Asset } from '../../../../../src/domain/model/model.js';
import { Identity } from '../../../../../src/domain/model/asset.model.js';

// 64-bit (16 hex char) hashes with known Hamming distances from ZERO.
const ZERO = '0000000000000000';
const DIST_1 = '0000000000000001'; // 1 bit set -> distance 1, similarity 98.4
const DIST_8 = '00000000000000ff'; // 8 bits set -> distance 8, similarity 87.5

async function setup(db: DbClient): Promise<{
  projectId: string;
  algorithmId: number;
  hashes: DrizzleAssetHashRepository;
  duplicates: DrizzleAssetHashDuplicateRepository;
  search: DrizzleClusterSearchRepository;
}> {
  const project = await makeProject(db);
  const algorithm = await makeAlgorithm(db);
  const clusters = new DrizzleClusterRepository(db);
  const duplicates = new DrizzleAssetHashDuplicateRepository(db, clusters);

  return {
    projectId: project.id,
    algorithmId: algorithm.id,
    hashes: new DrizzleAssetHashRepository(db),
    duplicates,
    search: new DrizzleClusterSearchRepository(db, clusters),
  };
}

/** Gives `a` and `b` a shared hash and recomputes both — an exact-comparison edge is always similarity 100. */
async function connect(
  hashes: DrizzleAssetHashRepository,
  duplicates: DrizzleAssetHashDuplicateRepository,
  projectId: string,
  algorithmId: number,
  a: Asset,
  b: Asset,
  sharedHash: string,
): Promise<void> {
  await hashes.replaceAll(a.id, algorithmId, [sharedHash]);
  await hashes.replaceAll(b.id, algorithmId, [sharedHash]);
  await duplicates.recomputeExact(projectId, algorithmId, a.id);
  await duplicates.recomputeExact(projectId, algorithmId, b.id);
}

describe('DrizzleClusterSearchRepository', () => {
  const { db } = useTestDb();

  describe('paginate', () => {
    it('returns an empty page when there are no qualifying edges', async () => {
      const { search, projectId, algorithmId } = await setup(db());

      const result = await search.paginate({ projectId, algorithmId, minSimilarity: 90 }, 1, 10);

      expect(result.page.getTotalCount()).toBe(0);
      expect(result.page.getData()).toEqual([]);
      expect(result.generation).toBeGreaterThanOrEqual(0);
    });

    it('returns one cluster with both members and their avg similarity', async () => {
      const { search, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared');

      const result = await search.paginate({ projectId, algorithmId, minSimilarity: 90 }, 1, 10);

      expect(result.page.getTotalCount()).toBe(1);
      const cluster = result.page.getData()[0];
      expect(cluster?.maxSimilarity).toBe(100);
      expect(cluster?.assets).toEqual(
        expect.arrayContaining([
          { identity: new Identity('a', null), avgSimilarityToCluster: 100 },
          { identity: new Identity('b', null), avgSimilarityToCluster: 100 },
        ]),
      );
      expect(cluster?.assets).toHaveLength(2);
    });

    it('groups a multi-hop chain (A-B-C, no direct A-C edge) into one cluster of 3', async () => {
      const { search, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      const c = await makeAsset(db(), projectId, 'c');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared-ab');
      await connect(hashes, duplicates, projectId, algorithmId, b, c, 'shared-bc');

      const result = await search.paginate({ projectId, algorithmId, minSimilarity: 90 }, 1, 10);

      expect(result.page.getTotalCount()).toBe(1);
      expect(result.page.getData()[0]?.assets).toHaveLength(3);
    });

    it('keeps two disconnected components as two separate clusters and paginates them', async () => {
      const { search, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      const c = await makeAsset(db(), projectId, 'c');
      const d = await makeAsset(db(), projectId, 'd');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared-ab');
      await connect(hashes, duplicates, projectId, algorithmId, c, d, 'shared-cd');

      const fullResult = await search.paginate({ projectId, algorithmId, minSimilarity: 90 }, 1, 10);
      expect(fullResult.page.getTotalCount()).toBe(2);
      expect(fullResult.page.getData()).toHaveLength(2);

      const firstPage = await search.paginate({ projectId, algorithmId, minSimilarity: 90 }, 1, 1);
      expect(firstPage.page.getData()).toHaveLength(1);
      expect(firstPage.page.hasNextPage()).toBe(true);
    });

    it('computes per-cluster maxSimilarity from the strongest qualifying edge in it', async () => {
      const { search, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      const c = await makeAsset(db(), projectId, 'c');
      // a<->b at distance 1 (similarity 98.4), a<->c at distance 8 (similarity 87.5) — both qualify above 80.
      await hashes.replaceAll(a.id, algorithmId, [ZERO]);
      await hashes.replaceAll(b.id, algorithmId, [DIST_1]);
      await hashes.replaceAll(c.id, algorithmId, [DIST_8]);
      await duplicates.recomputeHamming(projectId, algorithmId, a.id, 80);

      const result = await search.paginate({ projectId, algorithmId, minSimilarity: 80 }, 1, 10);

      expect(result.page.getTotalCount()).toBe(1);
      expect(result.page.getData()[0]?.maxSimilarity).toBeCloseTo(98.4, 1);
    });

    it('filters to clusters containing a member with this exact id, without narrowing maxSimilarity or membership to just that member', async () => {
      const { search, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      const c = await makeAsset(db(), projectId, 'c');
      // a<->b at 98.4% (the cluster's true max), a<->c at 87.5% — c's *own* edges are all <= 87.5%, so a
      // filter that wrongly narrows the aggregate to just `c`'s edges would report ~87.5 here instead.
      await hashes.replaceAll(a.id, algorithmId, [ZERO]);
      await hashes.replaceAll(b.id, algorithmId, [DIST_1]);
      await hashes.replaceAll(c.id, algorithmId, [DIST_8]);
      await duplicates.recomputeHamming(projectId, algorithmId, a.id, 80);

      const result = await search.paginate({ projectId, algorithmId, minSimilarity: 80, id: 'c' }, 1, 10);

      expect(result.page.getTotalCount()).toBe(1);
      const cluster = result.page.getData()[0];
      expect(cluster?.maxSimilarity).toBeCloseTo(98.4, 1);
      expect(cluster?.assets.map((asset) => asset.identity.id).sort()).toEqual(['a', 'b', 'c']);
    });

    it('filters to clusters containing a member whose path matches `*term*`', async () => {
      const { search, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const assetRepo = new DrizzleAssetRepository(db());
      const invoice = await assetRepo.create({
        projectId,
        identityId: null,
        identityPath: '/library/invoice-2024.pdf',
      });
      const other = await assetRepo.create({ projectId, identityId: null, identityPath: '/library/other.pdf' });
      const unrelated = await makeAsset(db(), projectId, 'unrelated');
      await hashes.replaceAll(invoice.id, algorithmId, [ZERO]);
      await hashes.replaceAll(other.id, algorithmId, [DIST_1]);
      await hashes.replaceAll(unrelated.id, algorithmId, [DIST_8]);
      await duplicates.recomputeHamming(projectId, algorithmId, invoice.id, 95);
      await duplicates.recomputeHamming(projectId, algorithmId, unrelated.id, 95);

      const result = await search.paginate({ projectId, algorithmId, minSimilarity: 80, path: '*invoice*' }, 1, 10);

      expect(result.page.getTotalCount()).toBe(1);
      expect(
        result.page
          .getData()[0]
          ?.assets.map((asset) => asset.identity.path)
          .sort(),
      ).toEqual(['/library/invoice-2024.pdf', '/library/other.pdf']);
    });

    it('returns an empty page when the id/path filter matches nothing', async () => {
      const { search, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared');

      const result = await search.paginate({ projectId, algorithmId, minSimilarity: 90, id: 'nope' }, 1, 10);

      expect(result.page.getTotalCount()).toBe(0);
      expect(result.page.getData()).toEqual([]);
    });

    it('pins to an earlier generation via query.generation, ignoring later writes', async () => {
      const { search, duplicates, hashes, projectId, algorithmId } = await setup(db());
      const a = await makeAsset(db(), projectId, 'a');
      const b = await makeAsset(db(), projectId, 'b');
      const c = await makeAsset(db(), projectId, 'c');
      await connect(hashes, duplicates, projectId, algorithmId, a, b, 'shared-ab');

      const first = await search.paginate({ projectId, algorithmId, minSimilarity: 90 }, 1, 10);
      expect(first.page.getTotalCount()).toBe(1);

      await connect(hashes, duplicates, projectId, algorithmId, b, c, 'shared-bc');

      const pinned = await search.paginate(
        { projectId, algorithmId, minSimilarity: 90, generation: first.generation },
        1,
        10,
      );
      expect(pinned.page.getData()[0]?.assets).toHaveLength(2);

      const current = await search.paginate({ projectId, algorithmId, minSimilarity: 90 }, 1, 10);
      expect(current.page.getData()[0]?.assets).toHaveLength(3);
    });

    it('throws ValidationError.tooManyDuplicateEdges when the edge count exceeds the safety cap', async () => {
      const fakeClusters = {
        countEdges: () => Promise.resolve(200_001),
        computeStats: () => Promise.reject(new Error('should not be called')),
        ensureFresh: () => Promise.reject(new Error('should not be called')),
      } as unknown as Clusters;
      const search = new DrizzleClusterSearchRepository({} as DbClient, fakeClusters);

      await expect(search.paginate({ projectId: 'p1', algorithmId: 1, minSimilarity: 90 }, 1, 10)).rejects.toThrow(
        ValidationError,
      );
    });
  });
});

import { describe, it, expect } from 'vitest';
import { DrizzleAssetRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.repository.js';
import { DrizzleAssetHashRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.hash.repository.js';
import { NotFoundError, AlreadyExistsError, ValidationError } from '../../../../../src/domain/errors.js';
import { Identity } from '../../../../../src/domain/model/asset.model.js';
import { useTestDb } from '../../../../helpers/db.js';
import { makeProject, makeAlgorithm } from '../../../../helpers/fixtures.js';

describe('DrizzleAssetRepository', () => {
  const { db } = useTestDb();

  describe('create', () => {
    it('creates a new asset row with id-only', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());

      const created = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: null });

      expect(created.id).toBeDefined();
      expect(created.identity).toEqual(new Identity('a1', null));
    });

    it('creates a new asset row with path-only', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());

      const created = await repo.create({ projectId: project.id, identityId: null, identityPath: 'photos/1.jpg' });

      expect(created.identity).toEqual(new Identity(null, 'photos/1.jpg'));
    });

    it('creates a new asset row with both id and path', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());

      const created = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: 'photos/1.jpg' });

      expect(created.identity).toEqual(new Identity('a1', 'photos/1.jpg'));
    });

    it('null on both fields at creation (nothing to keep) is rejected', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());

      await expect(repo.create({ projectId: project.id, identityId: null, identityPath: null })).rejects.toThrow(
        ValidationError,
      );
    });

    it('"" on both fields at creation is rejected the same as null', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());

      await expect(repo.create({ projectId: project.id, identityId: '', identityPath: '' })).rejects.toThrow(
        ValidationError,
      );
    });

    it('is idempotent when called again with the same id — no path change when path stays null', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());

      const first = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: null });
      const second = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: null });

      expect(second.id).toBe(first.id);
      expect(second.identity).toEqual(new Identity('a1', null));
    });

    it('null on a field keeps the previous value while the other field is replaced', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      const created = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: 'photos/1.jpg' });

      const updated = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: 'photos/2.jpg' });

      expect(updated.id).toBe(created.id);
      expect(updated.identity).toEqual(new Identity('a1', 'photos/2.jpg'));
    });

    it('"" clears a previously set field while null on the other keeps it', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      const created = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: 'photos/1.jpg' });

      const updated = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: '' });

      expect(updated.id).toBe(created.id);
      expect(updated.identity).toEqual(new Identity('a1', null));
    });

    it('rejects clearing the only field that made the identity valid', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      await repo.create({ projectId: project.id, identityId: 'a1', identityPath: null });

      await expect(repo.create({ projectId: project.id, identityId: '', identityPath: null })).rejects.toThrow(
        ValidationError,
      );
    });

    it('matches the previous row by path when only path is given, even if it also has an id', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      const created = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: 'photos/1.jpg' });

      // No id given at all — must fall back to matching by path, and must not touch the existing id.
      const updated = await repo.create({ projectId: project.id, identityId: null, identityPath: 'photos/1.jpg' });

      expect(updated.id).toBe(created.id);
      expect(updated.identity).toEqual(new Identity('a1', 'photos/1.jpg'));
    });

    it('does not throw AlreadyExistsError when id and path both resolve to the same existing row', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      const created = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: 'photos/1.jpg' });

      // Both `--id` and `--path` are given and both match — but the same row, not two different ones, so
      // this must be treated as a no-op re-affirmation, not a genuine id/path conflict.
      const updated = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: 'photos/1.jpg' });

      expect(updated.id).toBe(created.id);
      expect(updated.identity).toEqual(new Identity('a1', 'photos/1.jpg'));
    });

    it('throws AlreadyExistsError when id matches one row and path matches a different row', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      await repo.create({ projectId: project.id, identityId: 'a1', identityPath: null });
      await repo.create({ projectId: project.id, identityId: null, identityPath: 'photos/1.jpg' });

      await expect(
        repo.create({ projectId: project.id, identityId: 'a1', identityPath: 'photos/1.jpg' }),
      ).rejects.toThrow(AlreadyExistsError);
    });

    it('the same identity in two different projects are distinct assets', async () => {
      const projectA = await makeProject(db());
      const projectB = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());

      const a = await repo.create({ projectId: projectA.id, identityId: 'shared-id', identityPath: null });
      const b = await repo.create({ projectId: projectB.id, identityId: 'shared-id', identityPath: null });

      expect(a.id).not.toBe(b.id);
    });
  });

  describe('findByIdentity / getByIdentity', () => {
    it('finds an existing asset by id, and returns null otherwise', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      await repo.create({ projectId: project.id, identityId: 'a1', identityPath: null });

      await expect(repo.findByIdentity(project.id, new Identity('a1', null))).resolves.not.toBeNull();
      await expect(repo.findByIdentity(project.id, new Identity('nope', null))).resolves.toBeNull();
    });

    it('finds an existing asset by path', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      await repo.create({ projectId: project.id, identityId: null, identityPath: 'photos/1.jpg' });

      await expect(repo.findByIdentity(project.id, new Identity(null, 'photos/1.jpg'))).resolves.not.toBeNull();
    });

    it('looks up by id only when both id and path are given — id takes priority over path', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      const created = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: 'photos/1.jpg' });

      // A path that matches nothing, paired with a valid id, still finds the row — path is ignored once id is given.
      const found = await repo.findByIdentity(project.id, new Identity('a1', 'not-the-real-path'));

      expect(found?.id).toBe(created.id);
    });

    it('getByIdentity resolves to the asset when it exists', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      const created = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: null });

      const found = await repo.getByIdentity(project.id, new Identity('a1', null));

      expect(found.id).toBe(created.id);
    });

    it('getByIdentity throws NotFoundError when the asset does not exist', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());

      await expect(repo.getByIdentity(project.id, new Identity('nope', null))).rejects.toThrow(NotFoundError);
    });
  });

  describe('deleteByIdentity', () => {
    it('removes the asset by id (idempotent on repeat)', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      await repo.create({ projectId: project.id, identityId: 'a1', identityPath: null });

      await repo.deleteByIdentity(project.id, new Identity('a1', null));

      await expect(repo.findByIdentity(project.id, new Identity('a1', null))).resolves.toBeNull();
      await expect(repo.deleteByIdentity(project.id, new Identity('a1', null))).resolves.toBeUndefined();
    });

    it('removes the asset by path', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      await repo.create({ projectId: project.id, identityId: null, identityPath: 'photos/1.jpg' });

      await repo.deleteByIdentity(project.id, new Identity(null, 'photos/1.jpg'));

      await expect(repo.findByIdentity(project.id, new Identity(null, 'photos/1.jpg'))).resolves.toBeNull();
    });
  });

  describe('other repository methods (unaffected by the identity split)', () => {
    it('countByProject counts only assets in that project', async () => {
      const projectA = await makeProject(db());
      const projectB = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      await repo.create({ projectId: projectA.id, identityId: 'a1', identityPath: null });
      await repo.create({ projectId: projectA.id, identityId: 'a2', identityPath: null });
      await repo.create({ projectId: projectB.id, identityId: 'b1', identityPath: null });

      await expect(repo.countByProject(projectA.id)).resolves.toBe(2);
      await expect(repo.countByProject(projectB.id)).resolves.toBe(1);
    });

    it('countByProject returns a real number, not driver bigint-as-string', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      await repo.create({ projectId: project.id, identityId: 'a1', identityPath: null });

      expect(typeof (await repo.countByProject(project.id))).toBe('number');
    });

    it('listRecipes returns the distinct recipes hashed for an asset, looked up by identity', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetRepository(db());
      const asset = await repo.create({ projectId: project.id, identityId: 'a1', identityPath: null });
      const algorithmA = await makeAlgorithm(db(), { recipe: 'binary.sha256' });
      const algorithmB = await makeAlgorithm(db(), { recipe: 'image.phash16' });
      const hashRepo = new DrizzleAssetHashRepository(db());
      await hashRepo.replaceAll(asset.id, algorithmA.id, ['h1']);
      await hashRepo.replaceAll(asset.id, algorithmB.id, ['h2']);

      const recipes = await repo.listRecipes(project.id, new Identity('a1', null));

      expect(recipes.sort()).toEqual(['binary.sha256', 'image.phash16']);
    });

