import { describe, it, expect, vi } from 'vitest';
import { DrizzleAssetHashDuplicateRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.hashDuplicate.repository.js';
import { DrizzleClusterRepository } from '../../../../../src/infrastructure/drizzle/repository/cluster.repository.js';
import {
  DrizzleAssetHashDuplicateSearchRepository,
  createRankingAdapter,
  createMatchesAdapter,
} from '../../../../../src/infrastructure/drizzle/repository/asset.hashDuplicate.search.repository.js';
import { DrizzleAssetHashRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.hash.repository.js';
import { DrizzleAssetRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.repository.js';
import type { DbClient } from '../../../../../src/infrastructure/drizzle/client.js';
import { Identity } from '../../../../../src/domain/model/asset.model.js';
import { useTestDb } from '../../../../helpers/db.js';
import { makeProject, makeAsset, makeAlgorithm } from '../../../../helpers/fixtures.js';

// 64-bit (16 hex char) hashes with known Hamming distances from ZERO.
const ZERO = '0000000000000000';
const DIST_1 = '0000000000000001'; // 1 bit set -> distance 1, similarity 98.4
const DIST_4 = '000000000000000f'; // 4 bits set -> distance 4, similarity 93.8
const DIST_8 = '00000000000000ff'; // 8 bits set -> distance 8, similarity 87.5
const ALL_F = 'ffffffffffffffff'; // 64 bits set -> distance 64 from ZERO, similarity 0
const ALL_F_MINUS_1 = 'fffffffffffffffe'; // 63 bits set -> distance 1 from ALL_F, similarity 98.4

async function setup(db: DbClient): Promise<{
  project: Awaited<ReturnType<typeof makeProject>>;
  algorithm: Awaited<ReturnType<typeof makeAlgorithm>>;
  hashRepo: DrizzleAssetHashRepository;
  duplicates: DrizzleAssetHashDuplicateRepository;
  search: DrizzleAssetHashDuplicateSearchRepository;
}> {
  const project = await makeProject(db);
  const algorithm = await makeAlgorithm(db);
  const duplicates = new DrizzleAssetHashDuplicateRepository(db, new DrizzleClusterRepository(db));

  return {
    project,
    algorithm,
    hashRepo: new DrizzleAssetHashRepository(db),
    duplicates,
    search: new DrizzleAssetHashDuplicateSearchRepository(db, duplicates),
  };
}

describe('DrizzleAssetHashDuplicateSearchRepository', () => {
  const { db } = useTestDb();

  describe('paginate', () => {
    it('counts and ranks assets by duplicate count, descending, tie-broken by identity', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      // a<->b, a<->c: a has 2 duplicates, b and c have 1 each.
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(c.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const result = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0 },
        1,
        10,
      );

      expect(result.getTotalCount()).toBe(3);
      expect(result.getData()[0]?.identity.id).toBe('a');
      expect(result.getData()[0]?.duplicateCount).toBe(2);
      expect(
        result
          .getData()
          .slice(1)
          .map((r) => r.identity.id),
      ).toEqual(['b', 'c']);
    });

    it('returns totalCount and duplicateCount as real numbers, not driver bigint-as-string', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const result = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0 },
        1,
        10,
      );

      expect(typeof result.getTotalCount()).toBe('number');
      expect(typeof result.getData()[0]?.duplicateCount).toBe('number');
    });

    it('fills in matches per asset via one batched findByAssets call, sorted by descending similarity', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const result = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0 },
        1,
        10,
      );

      const a1 = result.getData().find((row) => row.identity.id === 'a');
      expect(a1?.matches).toEqual([{ identity: new Identity('b', null), distance: 1, similarity: 98.4 }]);
    });

    it("sorts an asset's matches by descending similarity when it has more than one", async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      const d = await makeAsset(db(), project.id, 'd');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_8]); // weakest match, similarity ~87.5
      await hashRepo.replaceAll(c.id, algorithm.id, [DIST_1]); // strongest match, similarity ~98.4
      await hashRepo.replaceAll(d.id, algorithm.id, [DIST_4]); // middle match, similarity ~93.8
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const result = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0 },
        1,
        10,
      );

      const a1 = result.getData().find((row) => row.identity.id === 'a');
      const similarities = a1?.matches.map((m) => m.similarity) ?? [];
      // Checked as a monotonic (non-increasing) sequence rather than a hardcoded order, so this doesn't
      // depend on whatever incidental row order Postgres happens to return before the sort runs — a
      // same-direction (ascending or coincidentally-matching) result from a broken comparator would fail
      // this for at least one adjacent pair among 3 distinct values.
      for (let i = 0; i < similarities.length - 1; i += 1) {
        expect(similarities[i]).toBeGreaterThanOrEqual(similarities[i + 1] ?? 0);
      }
      expect(a1?.matches.map((m) => m.identity.id)).toEqual(['c', 'd', 'b']);
    });

    it('caps matches per asset at matchLimit', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(c.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const result = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0, matchLimit: 1 },
        1,
        10,
      );

      const a1 = result.getData().find((row) => row.identity.id === 'a');
      expect(a1?.matches).toHaveLength(1);
    });

    it('paginates via Page, exposing hasNextPage()/hasPreviousPage()', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);
      const query = { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0 };

      const page1 = await search.paginateRanking(query, 1, 1);
      const page2 = await search.paginateRanking(query, 2, 1);

      expect(page1.getData()).toHaveLength(1);
      expect(page1.hasNextPage()).toBe(true);
      expect(page1.hasPreviousPage()).toBe(false);
      expect(page2.getData()).toHaveLength(1);
      expect(page2.hasNextPage()).toBe(false);
      expect(page2.hasPreviousPage()).toBe(true);
      expect(page1.getData()[0]?.identity.id).not.toBe(page2.getData()[0]?.identity.id);
    });

    it('returns the canonical empty result when nothing matches, without calling findByAssets', async () => {
      const { project, algorithm, search, duplicates } = await setup(db());
      const findByAssetsSpy = vi.spyOn(duplicates, 'findByAssets');

      const result = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0 },
        1,
        10,
      );

      expect(result.getData()).toEqual([]);
      expect(result.getTotalCount()).toBe(0);
      expect(findByAssetsSpy).not.toHaveBeenCalled();
    });

    it('filters by minSimilarity', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const strict = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 99 },
        1,
        10,
      );
      const lenient = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 90 },
        1,
        10,
      );

      expect(strict.getTotalCount()).toBe(0);
      expect(lenient.getTotalCount()).toBe(2);
    });

    it('attaches matches correctly when the ranked asset is identified by path rather than id', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      // `a` has no --id, only a path — exercises the identityKey() `id ?? ''` fallback branch,
      // since every other fixture in this file uses an id-based identity.
      const a = await new DrizzleAssetRepository(db()).create({
        projectId: project.id,
        identityId: null,
        identityPath: '/library/a.jpg',
      });
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const result = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0 },
        1,
        10,
      );

      const forA = result.getData().find((row) => row.identity.path === '/library/a.jpg');
      expect(forA?.identity.id).toBeNull();
      expect(forA?.matches).toEqual([{ identity: new Identity('b', null), distance: 1, similarity: 98.4 }]);
    });

    it('keeps matches separate for two different path-only assets, not just id-based ones', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const assetRepo = new DrizzleAssetRepository(db());
      // Two path-only assets — exercises the identityKey() `path ?? ''` fallback branch across two
      // *different* real paths. A bad fallback that discards the real path value (rather than defaulting
      // only when path is null) would collapse both onto the same map key and merge their matches.
      const a = await assetRepo.create({ projectId: project.id, identityId: null, identityPath: '/library/a.jpg' });
      const a2 = await assetRepo.create({
        projectId: project.id,
        identityId: null,
        identityPath: '/library/a2.jpg',
      });
      const x = await makeAsset(db(), project.id, 'x');
      const y = await makeAsset(db(), project.id, 'y');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(x.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(a2.id, algorithm.id, [ALL_F]);
      await hashRepo.replaceAll(y.id, algorithm.id, [ALL_F_MINUS_1]);
      // minSimilarity 50 at recompute time keeps only the intended a-x and a2-y pairs (each ~98.4%
      // similar) — every cross pair (a-a2, a-y, x-a2, x-y) is well under 5% similar and gets dropped.
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 50);
      await duplicates.recomputeHamming(project.id, algorithm.id, a2.id, 50);

      const result = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0 },
        1,
        10,
      );

      const forA = result.getData().find((row) => row.identity.path === '/library/a.jpg');
      const forA2 = result.getData().find((row) => row.identity.path === '/library/a2.jpg');
      expect(forA?.matches).toEqual([{ identity: new Identity('x', null), distance: 1, similarity: 98.4 }]);
      expect(forA2?.matches).toEqual([{ identity: new Identity('y', null), distance: 1, similarity: 98.4 }]);
    });

    it('filters by exact identity id when `id` is given', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const result = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0, id: 'a' },
        1,
        10,
      );

      expect(result.getTotalCount()).toBe(1);
      expect(result.getData()[0]?.identity.id).toBe('a');
    });

    it('filters by identity path via `*term*` search-query syntax when `path` is given', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const assetRepo = new DrizzleAssetRepository(db());
      const invoice = await assetRepo.create({
        projectId: project.id,
        identityId: null,
        identityPath: '/library/invoice-2024.pdf',
      });
      const photo = await assetRepo.create({
        projectId: project.id,
        identityId: null,
        identityPath: '/library/photo.jpg',
      });
      await hashRepo.replaceAll(invoice.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(photo.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, invoice.id, 0);

      const result = await search.paginateRanking(
        { projectId: project.id, algorithmId: algorithm.id, minSimilarity: 0, path: '*invoice*' },
        1,
        10,
      );

      expect(result.getTotalCount()).toBe(1);
      expect(result.getData()[0]?.identity.path).toBe('/library/invoice-2024.pdf');
    });
  });

  // `paginate()` only ever drives the adapter through `count()`/`pageView()` (page.size is
  // never null here), so `head()`/`all()` — required by the `HeadableAdapter`/`AllAdapter`
  // contracts, used by other callers such as admin tooling — are exercised directly against
  // the adapter. The adapter only ranks/counts (no matches) — matches are assembled one level up.
  describe('createRankingAdapter', () => {
    it('all() returns every ranked asset (no matches — adapter only ranks/counts)', async () => {
      const { project, algorithm, hashRepo, duplicates } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(c.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);
      const adapter = createRankingAdapter(db(), {
        projectId: project.id,
        algorithmId: algorithm.id,
        minSimilarity: 0,
      });

      const rows = await adapter.all();

      expect(rows).toHaveLength(3);
      expect(rows[0]).toEqual({ identityId: 'a', identityPath: null, duplicateCount: 2 });
    });

    it('head(size) applies the limit', async () => {
      const { project, algorithm, hashRepo, duplicates } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);
      const adapter = createRankingAdapter(db(), {
        projectId: project.id,
        algorithmId: algorithm.id,
        minSimilarity: 0,
      });

      await expect(adapter.head(1)).resolves.toHaveLength(1);
    });

    it('all() returns an empty array when nothing matches', async () => {
      const { project, algorithm } = await setup(db());
      const adapter = createRankingAdapter(db(), {
        projectId: project.id,
        algorithmId: algorithm.id,
        minSimilarity: 0,
      });

      await expect(adapter.all()).resolves.toEqual([]);
    });
  });

  describe('paginateMatches', () => {
    it("returns one asset's matches, sorted by descending similarity", async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(c.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeExact(project.id, algorithm.id, a.id);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const result = await search.paginateMatches(
        { projectId: project.id, algorithmId: algorithm.id, identity: new Identity('a', null), minSimilarity: 0 },
        1,
        10,
      );

      expect(result.getTotalCount()).toBe(2);
      expect(result.getData().map((m) => m.identity.id)).toEqual(['b', 'c']); // b: 100% exact, c: 98.4% hamming
    });

    it('scopes to the requested asset only', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(c.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const forA = await search.paginateMatches(
        { projectId: project.id, algorithmId: algorithm.id, identity: new Identity('a', null), minSimilarity: 0 },
        1,
        10,
      );
      const forB = await search.paginateMatches(
        { projectId: project.id, algorithmId: algorithm.id, identity: new Identity('b', null), minSimilarity: 0 },
        1,
        10,
      );

      expect(forA.getTotalCount()).toBe(2); // a<->b, a<->c
      expect(forB.getTotalCount()).toBe(1); // b<->a only (b<->c was never computed)
    });

    it('paginates via Page', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(c.id, algorithm.id, [ZERO]);
      await duplicates.recomputeExact(project.id, algorithm.id, a.id);
      const query = {
        projectId: project.id,
        algorithmId: algorithm.id,
        identity: new Identity('a', null),
        minSimilarity: 0,
      };

      const page1 = await search.paginateMatches(query, 1, 1);

      expect(page1.getData()).toHaveLength(1);
      expect(page1.getTotalCount()).toBe(2);
      expect(page1.hasNextPage()).toBe(true);
      expect(page1.hasPreviousPage()).toBe(false);
    });

    it('returns the canonical empty result when the asset has no matches', async () => {
      const { project, algorithm, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');

      const result = await search.paginateMatches(
        {
          projectId: project.id,
          algorithmId: algorithm.id,
          identity: new Identity(a.identityId, a.identityPath),
          minSimilarity: 0,
        },
        1,
        10,
      );

      expect(result.getData()).toEqual([]);
      expect(result.getTotalCount()).toBe(0);
    });

    it('filters by minSimilarity', async () => {
      const { project, algorithm, hashRepo, duplicates, search } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);
      const base = { projectId: project.id, algorithmId: algorithm.id, identity: new Identity('a', null) };

      const strict = await search.paginateMatches({ ...base, minSimilarity: 99 }, 1, 10);
      const lenient = await search.paginateMatches({ ...base, minSimilarity: 90 }, 1, 10);

      expect(strict.getTotalCount()).toBe(0);
      expect(lenient.getTotalCount()).toBe(1);
    });
  });

  // Same rationale as `createRankingAdapter` above — `head()`/`all()` aren't reached by
  // `paginateMatches()` (page.size is never null here), so they're tested directly.
  describe('createMatchesAdapter', () => {
    it('all() returns every match', async () => {
      const { project, algorithm, hashRepo, duplicates } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(c.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);
      const adapter = createMatchesAdapter(db(), {
        projectId: project.id,
        algorithmId: algorithm.id,
        identity: new Identity('a', null),
        minSimilarity: 0,
      });

      await expect(adapter.all()).resolves.toHaveLength(2);
    });

    it('head(size) applies the limit', async () => {
      const { project, algorithm, hashRepo, duplicates } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(c.id, algorithm.id, [DIST_1]);
      await duplicates.recomputeHamming(project.id, algorithm.id, a.id, 0);
      const adapter = createMatchesAdapter(db(), {
        projectId: project.id,
        algorithmId: algorithm.id,
        identity: new Identity('a', null),
        minSimilarity: 0,
      });

      await expect(adapter.head(1)).resolves.toHaveLength(1);
    });

    it('all() returns an empty array when nothing matches', async () => {
      const { project, algorithm } = await setup(db());
      const adapter = createMatchesAdapter(db(), {
        projectId: project.id,
        algorithmId: algorithm.id,
        identity: new Identity('a', null),
        minSimilarity: 0,
      });

      await expect(adapter.all()).resolves.toEqual([]);
    });
  });
});

import { describe, it, expect } from 'vitest';
import { DrizzleProjectRepository } from '../../../../../src/infrastructure/drizzle/repository/project.repository.js';
import { useTestDb } from '../../../../helpers/db.js';
import { makeProject } from '../../../../helpers/fixtures.js';
import { NotFoundError, AlreadyExistsError } from '../../../../../src/domain/errors.js';

describe('DrizzleProjectRepository', () => {
  const { db } = useTestDb();

  it('creates a project and finds it by id and slug', async () => {
    const repo = new DrizzleProjectRepository(db());

    const created = await repo.create({
      slug: 'demo',
      name: 'Demo',
      recipes: ['binary.sha256'],
      hammingThreshold: null,
    });

    expect(created.id).toBeDefined();
    await expect(repo.findById(created.id)).resolves.toEqual(created);
    await expect(repo.findBySlug('demo')).resolves.toEqual(created);
  });

  it('findById/findBySlug return null when not found', async () => {
    const repo = new DrizzleProjectRepository(db());

    await expect(repo.findBySlug('nope')).resolves.toBeNull();
    await expect(repo.findById('00000000-0000-0000-0000-000000000000')).resolves.toBeNull();
  });

  it('getBySlug throws NotFoundError when the project does not exist', async () => {
    const repo = new DrizzleProjectRepository(db());

    await expect(repo.getBySlug('nope')).rejects.toThrow(NotFoundError);
  });

  it('getBySlug returns the project when it exists', async () => {
    const created = await makeProject(db(), { slug: 'demo' });
    const repo = new DrizzleProjectRepository(db());

    await expect(repo.getBySlug('demo')).resolves.toEqual(created);
  });

  it('list returns all projects ordered by slug', async () => {
    await makeProject(db(), { slug: 'zeta' });
    await makeProject(db(), { slug: 'alpha' });
    const repo = new DrizzleProjectRepository(db());

    const projects = await repo.list();

    expect(projects.map((p) => p.slug)).toEqual(['alpha', 'zeta']);
  });

  it('rejects creating a project with a duplicate slug as AlreadyExistsError', async () => {
    await makeProject(db(), { slug: 'demo' });
    const repo = new DrizzleProjectRepository(db());

    await expect(
      repo.create({ slug: 'demo', name: 'Demo 2', recipes: ['binary.sha256'], hammingThreshold: null }),
    ).rejects.toThrow(AlreadyExistsError);
  });

  it('re-throws a non-unique-violation error as-is (e.g. slug exceeding the column length)', async () => {
    const repo = new DrizzleProjectRepository(db());

    await expect(
      repo.create({ slug: 'x'.repeat(100), name: 'Demo', recipes: ['binary.sha256'], hammingThreshold: null }),
    ).rejects.not.toBeInstanceOf(AlreadyExistsError);
  });

  it('updateSettings updates recipes and hammingThreshold', async () => {
    const created = await makeProject(db(), { slug: 'demo' });
    const repo = new DrizzleProjectRepository(db());

    const updated = await repo.updateSettings(created.id, {
      recipes: ['binary.sha256', 'image.phash16'],
      hammingThreshold: 95,
    });

    expect(updated.recipes).toEqual(['binary.sha256', 'image.phash16']);
    expect(updated.hammingThreshold).toBe(95);
  });

  it('updateSettings updates the name, leaving recipes/hammingThreshold untouched', async () => {
    const created = await makeProject(db(), { slug: 'demo', name: 'Old Name' });
    const repo = new DrizzleProjectRepository(db());

    const updated = await repo.updateSettings(created.id, { name: 'New Name' });

    expect(updated.name).toBe('New Name');
    expect(updated.recipes).toEqual(created.recipes);
    expect(updated.hammingThreshold).toBe(created.hammingThreshold);
  });

  it('updateSettings updates rateLimitPerMinute, leaving other fields untouched', async () => {
    const created = await makeProject(db(), { slug: 'demo' });
    const repo = new DrizzleProjectRepository(db());

    const updated = await repo.updateSettings(created.id, { rateLimitPerMinute: 50 });

    expect(updated.rateLimitPerMinute).toBe(50);
    expect(updated.recipes).toEqual(created.recipes);
    expect(updated.hammingThreshold).toBe(created.hammingThreshold);
  });

  it('updateSettings throws NotFoundError for a nonexistent id', async () => {
    const repo = new DrizzleProjectRepository(db());

    await expect(
      repo.updateSettings('00000000-0000-0000-0000-000000000000', { recipes: ['binary.sha256'] }),
    ).rejects.toThrow(NotFoundError);
  });

  it('deleteById removes the project (idempotent on repeat)', async () => {
    const created = await makeProject(db(), { slug: 'demo' });
    const repo = new DrizzleProjectRepository(db());

    await repo.deleteById(created.id);
    await expect(repo.findById(created.id)).resolves.toBeNull();
    await expect(repo.deleteById(created.id)).resolves.toBeUndefined();
  });
});

import { describe, it, expect } from 'vitest';
import { DrizzleAssetHashDuplicateRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.hashDuplicate.repository.js';
import { DrizzleClusterRepository } from '../../../../../src/infrastructure/drizzle/repository/cluster.repository.js';
import { DrizzleAssetHashRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.hash.repository.js';
import type { DbClient } from '../../../../../src/infrastructure/drizzle/client.js';
import { Identity } from '../../../../../src/domain/model/asset.model.js';
import { useTestDb } from '../../../../helpers/db.js';
import { makeProject, makeAsset, makeAlgorithm } from '../../../../helpers/fixtures.js';

// 64-bit (16 hex char) hashes with known Hamming distances from ZERO.
const ZERO = '0000000000000000';
const DIST_1 = '0000000000000001'; // 1 bit set -> distance 1, similarity 98.4
const DIST_8 = '00000000000000ff'; // 8 bits set -> distance 8, similarity 87.5
const FAR = 'ffffffffffffffff'; // all bits set -> distance 64, similarity 0

async function setup(db: DbClient): Promise<{
  project: Awaited<ReturnType<typeof makeProject>>;
  algorithm: Awaited<ReturnType<typeof makeAlgorithm>>;
  hashRepo: DrizzleAssetHashRepository;
}> {
  const project = await makeProject(db);
  const algorithm = await makeAlgorithm(db);
  const hashRepo = new DrizzleAssetHashRepository(db);

  return { project, algorithm, hashRepo };
}

describe('DrizzleAssetHashDuplicateRepository', () => {
  const { db } = useTestDb();

  describe('recomputeExact', () => {
    it('creates a distance-0/similarity-100 row for assets sharing a hash', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, ['shared-hash']);
      await hashRepo.replaceAll(b.id, algorithm.id, ['shared-hash']);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));

      await repo.recomputeExact(project.id, algorithm.id, a.id);

      const matches = await repo.findByAssets(project.id, [new Identity('a', null)], algorithm.id, 0);
      expect(matches).toEqual([
        { identity: new Identity('a', null), otherIdentity: new Identity('b', null), distance: 0, similarity: 100 },
      ]);
    });

    it('does not match assets with no shared hash', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, ['hash-a']);
      await hashRepo.replaceAll(b.id, algorithm.id, ['hash-b']);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));

      await repo.recomputeExact(project.id, algorithm.id, a.id);

      await expect(repo.findByAssets(project.id, [new Identity('a', null)], algorithm.id, 0)).resolves.toEqual([]);
    });
  });

  describe('recomputeHamming', () => {
    it('stores the minimum distance and its derived similarity when above the threshold', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));

      await repo.recomputeHamming(project.id, algorithm.id, a.id, 90);

      const matches = await repo.findByAssets(project.id, [new Identity('a', null)], algorithm.id, 0);
      expect(matches).toEqual([
        { identity: new Identity('a', null), otherIdentity: new Identity('b', null), distance: 1, similarity: 98.4 },
      ]);
    });

    it('does not store a pair below the similarity threshold', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [FAR]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));

      await repo.recomputeHamming(project.id, algorithm.id, a.id, 90);

      await expect(repo.findByAssets(project.id, [new Identity('a', null)], algorithm.id, 0)).resolves.toEqual([]);
    });

    it('upserts — a second recompute updates distance/similarity in place', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));
      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);

      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_8]);
      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const matches = await repo.findByAssets(project.id, [new Identity('a', null)], algorithm.id, 0);
      expect(matches).toEqual([
        { identity: new Identity('a', null), otherIdentity: new Identity('b', null), distance: 8, similarity: 87.5 },
      ]);
    });

    it('keeps the minimum distance across multiple hashes (multi-frame) per candidate', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO, DIST_8]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));

      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const matches = await repo.findByAssets(project.id, [new Identity('a', null)], algorithm.id, 0);
      expect(matches[0]?.distance).toBe(1); // ZERO vs DIST_1, the closer of the two frame comparisons
    });
  });

  describe('deleteByAsset', () => {
    it('removes rows touching the asset from either side, scoped to the algorithm', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));
      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);

      await repo.deleteByAsset(algorithm.id, a.id);

      await expect(
        repo.findByAssets(project.id, [new Identity('a', null), new Identity('b', null)], algorithm.id, 0),
      ).resolves.toEqual([]);
    });
  });

  describe('deleteByProject', () => {
    it('clears all rows for (project, algorithm) without touching other algorithms', async () => {
      const project = await makeProject(db());
      const algorithm = await makeAlgorithm(db());
      const otherAlgorithm = await makeAlgorithm(db());
      const hashRepo = new DrizzleAssetHashRepository(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(a.id, otherAlgorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, otherAlgorithm.id, [DIST_1]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));
      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);
      await repo.recomputeHamming(project.id, otherAlgorithm.id, a.id, 0);

      await repo.deleteByProject(project.id, algorithm.id);

      await expect(repo.findByAssets(project.id, [new Identity('a', null)], algorithm.id, 0)).resolves.toEqual([]);
      await expect(
        repo.findByAssets(project.id, [new Identity('a', null)], otherAlgorithm.id, 0),
      ).resolves.toHaveLength(1);
    });
  });

  describe('findByProject', () => {
    it('returns one row per edge with both identities resolved, scoped to the project', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const otherProject = await makeProject(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const outside = await makeAsset(db(), otherProject.id, 'outside');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(outside.id, algorithm.id, [ZERO]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));
      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);

      const edges = await repo.findByProject(project.id, algorithm.id, 0);

      expect(edges).toHaveLength(1);
      const edge = edges[0];
      expect([edge?.identityA.id, edge?.identityB.id].sort()).toEqual(['a', 'b']);
      expect(edge?.distance).toBe(1);
      expect(edge?.similarity).toBe(98.4);
    });

    it('filters by minSimilarity', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_8]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));
      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);

      await expect(repo.findByProject(project.id, algorithm.id, 90)).resolves.toEqual([]);
      await expect(repo.findByProject(project.id, algorithm.id, 80)).resolves.toHaveLength(1);
    });
  });

  describe('findByAssets', () => {
    it('returns matches for multiple requested identities in a single call, regardless of which side they are stored on', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(c.id, algorithm.id, [DIST_1]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));
      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);
      await repo.recomputeHamming(project.id, algorithm.id, b.id, 0);

      const matches = await repo.findByAssets(
        project.id,
        [new Identity('a', null), new Identity('b', null)],
        algorithm.id,
        0,
      );

      expect(matches.map((m) => `${m.identity.id ?? ''}->${m.otherIdentity.id ?? ''}`).sort()).toEqual(
        ['a->b', 'a->c', 'b->a', 'b->c'].sort(),
      );
    });

    it('returns an empty array for an empty identities list without querying', async () => {
      const { project, algorithm } = await setup(db());
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));

      await expect(repo.findByAssets(project.id, [], algorithm.id, 0)).resolves.toEqual([]);
    });
  });

  describe('countPairsByProject', () => {
    it('counts distinct pairs once, not the doubled directional row count', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const c = await makeAsset(db(), project.id, 'c');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(c.id, algorithm.id, [DIST_1]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));
      // a<->b, a<->c: 2 pairs, 4 directional rows in storage.
      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);

      await expect(repo.countPairsByProject(project.id)).resolves.toBe(2);
    });

    it('sums pairs across every algorithm in the project', async () => {
      const project = await makeProject(db());
      const algorithmA = await makeAlgorithm(db());
      const algorithmB = await makeAlgorithm(db());
      const hashRepo = new DrizzleAssetHashRepository(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithmA.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithmA.id, [DIST_1]);
      await hashRepo.replaceAll(a.id, algorithmB.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithmB.id, [DIST_1]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));
      await repo.recomputeHamming(project.id, algorithmA.id, a.id, 0);
      await repo.recomputeHamming(project.id, algorithmB.id, a.id, 0);

      await expect(repo.countPairsByProject(project.id)).resolves.toBe(2);
    });

    it('does not count pairs from other projects', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const otherProject = await makeProject(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      const outsideA = await makeAsset(db(), otherProject.id, 'outside-a');
      const outsideB = await makeAsset(db(), otherProject.id, 'outside-b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      await hashRepo.replaceAll(outsideA.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(outsideB.id, algorithm.id, [DIST_1]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));
      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);
      await repo.recomputeHamming(otherProject.id, algorithm.id, outsideA.id, 0);

      await expect(repo.countPairsByProject(project.id)).resolves.toBe(1);
    });

    it('returns zero for a project with no duplicates', async () => {
      const project = await makeProject(db());
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));

      await expect(repo.countPairsByProject(project.id)).resolves.toBe(0);
    });

    it('returns a real number, not driver bigint-as-string', async () => {
      const { project, algorithm, hashRepo } = await setup(db());
      const a = await makeAsset(db(), project.id, 'a');
      const b = await makeAsset(db(), project.id, 'b');
      await hashRepo.replaceAll(a.id, algorithm.id, [ZERO]);
      await hashRepo.replaceAll(b.id, algorithm.id, [DIST_1]);
      const repo = new DrizzleAssetHashDuplicateRepository(db(), new DrizzleClusterRepository(db()));
      await repo.recomputeHamming(project.id, algorithm.id, a.id, 0);

      expect(typeof (await repo.countPairsByProject(project.id))).toBe('number');
    });
  });
});

import { describe, it, expect } from 'vitest';
import { DrizzleAssetHashRepository } from '../../../../../src/infrastructure/drizzle/repository/asset.hash.repository.js';
import { useTestDb } from '../../../../helpers/db.js';
import { makeProject, makeAsset, makeAlgorithm } from '../../../../helpers/fixtures.js';

describe('DrizzleAssetHashRepository', () => {
  const { db } = useTestDb();

  it('replaceAll inserts hashes for an asset+algorithm, sequence-indexed', async () => {
    const project = await makeProject(db());
    const asset = await makeAsset(db(), project.id);
    const algorithm = await makeAlgorithm(db());
    const repo = new DrizzleAssetHashRepository(db());

    await repo.replaceAll(asset.id, algorithm.id, ['hash-0', 'hash-1']);

    const first = await repo.findOne(asset.id, algorithm.id, 0);
    const second = await repo.findOne(asset.id, algorithm.id, 1);

    expect(first?.hash).toBe('hash-0');
    expect(second?.hash).toBe('hash-1');
  });

  it('findOne returns null when nothing matches', async () => {
    const project = await makeProject(db());
    const asset = await makeAsset(db(), project.id);
    const algorithm = await makeAlgorithm(db());
    const repo = new DrizzleAssetHashRepository(db());

    await expect(repo.findOne(asset.id, algorithm.id, 0)).resolves.toBeNull();
  });

  it('replaceAll on the same (asset, algorithm) fully replaces the previous hashes', async () => {
    const project = await makeProject(db());
    const asset = await makeAsset(db(), project.id);
    const algorithm = await makeAlgorithm(db());
    const repo = new DrizzleAssetHashRepository(db());

    await repo.replaceAll(asset.id, algorithm.id, ['old-0', 'old-1', 'old-2']);
    await repo.replaceAll(asset.id, algorithm.id, ['new-0']);

    const all = await repo.findByAssetId(asset.id);
    expect(all).toHaveLength(1);
    expect(all[0]?.hash).toBe('new-0');
  });

  it('replaceAll with an empty array clears existing hashes', async () => {
    const project = await makeProject(db());
    const asset = await makeAsset(db(), project.id);
    const algorithm = await makeAlgorithm(db());
    const repo = new DrizzleAssetHashRepository(db());

    await repo.replaceAll(asset.id, algorithm.id, ['hash-0']);
    await repo.replaceAll(asset.id, algorithm.id, []);

    await expect(repo.findByAssetId(asset.id)).resolves.toEqual([]);
  });

  it('findByAssetId returns hashes across multiple algorithms for the asset', async () => {
    const project = await makeProject(db());
    const asset = await makeAsset(db(), project.id);
    const algorithmA = await makeAlgorithm(db());
    const algorithmB = await makeAlgorithm(db());
    const repo = new DrizzleAssetHashRepository(db());

    await repo.replaceAll(asset.id, algorithmA.id, ['hash-a']);
    await repo.replaceAll(asset.id, algorithmB.id, ['hash-b']);

    const all = await repo.findByAssetId(asset.id);
    expect(all.map((h) => h.hash).sort()).toEqual(['hash-a', 'hash-b']);
  });

  it('does not affect hashes belonging to a different asset', async () => {
    const project = await makeProject(db());
    const assetA = await makeAsset(db(), project.id, 'asset-a');
    const assetB = await makeAsset(db(), project.id, 'asset-b');
    const algorithm = await makeAlgorithm(db());
    const repo = new DrizzleAssetHashRepository(db());

    await repo.replaceAll(assetA.id, algorithm.id, ['hash-a']);
    await repo.replaceAll(assetB.id, algorithm.id, ['hash-b']);
    await repo.replaceAll(assetA.id, algorithm.id, []);

    await expect(repo.findByAssetId(assetA.id)).resolves.toEqual([]);
    await expect(repo.findByAssetId(assetB.id)).resolves.toHaveLength(1);
  });

  describe('countExactDuplicateStats', () => {
    it('returns zeroed stats when no hash is shared by more than one asset', async () => {
      const project = await makeProject(db());
      const algorithm = await makeAlgorithm(db());
      const repo = new DrizzleAssetHashRepository(db());
      const asset = await makeAsset(db(), project.id);
      await repo.replaceAll(asset.id, algorithm.id, ['unique-hash']);

      await expect(repo.countExactDuplicateStats(project.id, algorithm.id)).resolves.toEqual({
        clusterCount: 0,
        edgeCount: 0,
        assetsWithDuplicateCount: 0,
      });
    });

    it('groups assets sharing an identical hash into one group, edges = complete-graph pairs', async () => {
      const project = await makeProject(db());
      const algorithm = await makeAlgorithm(db());
      const repo = new DrizzleAssetHashRepository(db());

      // 3 assets share one hash (a 3-clique: 3 edges), 2 assets share another (1 edge).
      for (const identity of ['a', 'b', 'c']) {
        const asset = await makeAsset(db(), project.id, identity);
        await repo.replaceAll(asset.id, algorithm.id, ['shared-1']);
      }
      for (const identity of ['d', 'e']) {
        const asset = await makeAsset(db(), project.id, identity);
        await repo.replaceAll(asset.id, algorithm.id, ['shared-2']);
      }
      const lone = await makeAsset(db(), project.id, 'f');
      await repo.replaceAll(lone.id, algorithm.id, ['unique-hash']);

      const stats = await repo.countExactDuplicateStats(project.id, algorithm.id);

      expect(stats).toEqual({ clusterCount: 2, edgeCount: 4, assetsWithDuplicateCount: 5 });
    });

    it('scopes by project and algorithm — a shared hash in another project/algorithm does not count', async () => {
      const project = await makeProject(db());
      const otherProject = await makeProject(db());
      const algorithm = await makeAlgorithm(db());
      const otherAlgorithm = await makeAlgorithm(db());
      const repo = new DrizzleAssetHashRepository(db());

      const asset = await makeAsset(db(), project.id, 'a');
      await repo.replaceAll(asset.id, algorithm.id, ['shared']);
      const otherProjectAsset = await makeAsset(db(), otherProject.id, 'b');
      await repo.replaceAll(otherProjectAsset.id, algorithm.id, ['shared']);
      const otherAlgorithmAsset = await makeAsset(db(), project.id, 'c');
      await repo.replaceAll(otherAlgorithmAsset.id, otherAlgorithm.id, ['shared']);

      await expect(repo.countExactDuplicateStats(project.id, algorithm.id)).resolves.toEqual({
        clusterCount: 0,
        edgeCount: 0,
        assetsWithDuplicateCount: 0,
      });
    });
  });
});

import { describe, it, expect } from 'vitest';
import { DrizzleApiClientRepository } from '../../../../../src/infrastructure/drizzle/repository/apiClient.repository.js';
import { ApiScope } from '../../../../../src/domain/model/apiClient.model.js';
import { useTestDb } from '../../../../helpers/db.js';
import { makeProject, makeApiClient } from '../../../../helpers/fixtures.js';
import { NotFoundError, AlreadyExistsError } from '../../../../../src/domain/errors.js';

describe('DrizzleApiClientRepository', () => {
  const { db } = useTestDb();

  it('creates a client and finds it by key hash', async () => {
    const project = await makeProject(db());
    const repo = new DrizzleApiClientRepository(db());

    const created = await repo.create({
      projectId: project.id,
      name: 'ci',
      keyHash: 'hash-1',
      scopes: [ApiScope.ASSETS_READ],
    });

    await expect(repo.findByKeyHash('hash-1')).resolves.toEqual(created);
  });

  it('findByKeyHash returns null for an unknown key', async () => {
    const repo = new DrizzleApiClientRepository(db());

    await expect(repo.findByKeyHash('unknown')).resolves.toBeNull();
  });

  it('findByKeyHash does not return a revoked client', async () => {
    const project = await makeProject(db());
    const { apiClient } = await makeApiClient(db(), project.id);
    const repo = new DrizzleApiClientRepository(db());

    await repo.revoke(apiClient.id);

    await expect(repo.findByKeyHash(apiClient.keyHash)).resolves.toBeNull();
  });

  it('listByProject returns clients for the project ordered by creation time', async () => {
    const project = await makeProject(db());
    const repo = new DrizzleApiClientRepository(db());
    await repo.create({ projectId: project.id, name: 'first', keyHash: 'hash-1', scopes: [] });
    await repo.create({ projectId: project.id, name: 'second', keyHash: 'hash-2', scopes: [] });

    const clients = await repo.listByProject(project.id);

    expect(clients.map((c) => c.name)).toEqual(['first', 'second']);
  });

  it('listByProject excludes clients from other projects', async () => {
    const project = await makeProject(db());
    const otherProject = await makeProject(db());
    await makeApiClient(db(), project.id);
    await makeApiClient(db(), otherProject.id);
    const repo = new DrizzleApiClientRepository(db());

    const clients = await repo.listByProject(project.id);

    expect(clients).toHaveLength(1);
    expect(clients[0]?.projectId).toBe(project.id);
  });

  it('findByProjectAndName finds an active client by name', async () => {
    const project = await makeProject(db());
    const { apiClient } = await makeApiClient(db(), project.id, { name: 'ci' });
    const repo = new DrizzleApiClientRepository(db());

    await expect(repo.findByProjectAndName(project.id, 'ci')).resolves.toEqual(apiClient);
  });

  it('findByProjectAndName does not return a revoked client', async () => {
    const project = await makeProject(db());
    const { apiClient } = await makeApiClient(db(), project.id, { name: 'ci' });
    const repo = new DrizzleApiClientRepository(db());
    await repo.revoke(apiClient.id);

    await expect(repo.findByProjectAndName(project.id, 'ci')).resolves.toBeNull();
  });

  it('rejects creating a second active client with the same name in the same project', async () => {
    const project = await makeProject(db());
    const repo = new DrizzleApiClientRepository(db());
    await repo.create({ projectId: project.id, name: 'ci', keyHash: 'hash-1', scopes: [] });

    await expect(repo.create({ projectId: project.id, name: 'ci', keyHash: 'hash-2', scopes: [] })).rejects.toThrow(
      AlreadyExistsError,
    );
  });

  it('allows re-issuing a name after the original client was revoked', async () => {
    const project = await makeProject(db());
    const repo = new DrizzleApiClientRepository(db());
    const first = await repo.create({ projectId: project.id, name: 'ci', keyHash: 'hash-1', scopes: [] });
    await repo.revoke(first.id);

    await expect(
      repo.create({ projectId: project.id, name: 'ci', keyHash: 'hash-2', scopes: [] }),
    ).resolves.toBeDefined();
  });

  it('re-throws a non-unique-violation error as-is (e.g. a foreign key violation)', async () => {
    const repo = new DrizzleApiClientRepository(db());

    await expect(
      repo.create({
        projectId: '00000000-0000-0000-0000-000000000000',
        name: 'ci',
        keyHash: 'hash-1',
        scopes: [],
      }),
    ).rejects.not.toBeInstanceOf(AlreadyExistsError);
  });

  it('revoke throws NotFoundError for a nonexistent client', async () => {
    const repo = new DrizzleApiClientRepository(db());

    await expect(repo.revoke('00000000-0000-0000-0000-000000000000')).rejects.toThrow(NotFoundError);
  });

  it('revoke throws NotFoundError when the client is already revoked', async () => {
    const project = await makeProject(db());
    const { apiClient } = await makeApiClient(db(), project.id);
    const repo = new DrizzleApiClientRepository(db());
    await repo.revoke(apiClient.id);

    await expect(repo.revoke(apiClient.id)).rejects.toThrow(NotFoundError);
  });
});

import { describe, it, expect } from 'vitest';
import { DrizzleAlgorithmRepository } from '../../../../../src/infrastructure/drizzle/repository/algorithm.repository.js';
import { Comparison } from '../../../../../src/domain/model/algorithm.model.js';
import { useTestDb } from '../../../../helpers/db.js';

describe('DrizzleAlgorithmRepository', () => {
  const { db } = useTestDb();

  it('add creates a new algorithm row', async () => {
    const repo = new DrizzleAlgorithmRepository(db());

    const algorithm = await repo.add({ recipe: 'binary.sha256', comparison: Comparison.EXACT });

    expect(algorithm.id).toBeDefined();
    expect(algorithm.recipe).toBe('binary.sha256');
    expect(algorithm.comparison).toBe(Comparison.EXACT);
  });

  it('add is idempotent for the same recipe — returns the existing row instead of erroring', async () => {
    const repo = new DrizzleAlgorithmRepository(db());

    const first = await repo.add({ recipe: 'binary.sha256', comparison: Comparison.EXACT });
    const second = await repo.add({ recipe: 'binary.sha256', comparison: Comparison.EXACT });

    expect(second.id).toBe(first.id);
  });

  it('findByRecipe finds an existing algorithm, and returns null otherwise', async () => {
    const repo = new DrizzleAlgorithmRepository(db());
    const created = await repo.add({ recipe: 'image.phash16', comparison: Comparison.HAMMING });

    await expect(repo.findByRecipe('image.phash16')).resolves.toEqual(created);
    await expect(repo.findByRecipe('nope')).resolves.toBeNull();
  });
});

describe('DrizzleAlgorithmRepository — race condition on add()', () => {
  it('throws when the insert is skipped (conflict) and the immediate re-select also finds nothing', async () => {
    // Simulates the narrow window where a concurrent insert's row hasn't committed/become
    // visible yet: onConflictDoNothing() skips (no row), and the immediate re-select races it.
    interface FakeChain {
      insert: () => FakeChain;
      values: () => FakeChain;
      onConflictDoNothing: () => FakeChain;
      returning: () => Promise<never[]>;
      select: () => FakeChain;
      from: () => FakeChain;
      where: () => FakeChain;
      limit: () => Promise<never[]>;
    }

    const chain: FakeChain = {
      insert: (): FakeChain => chain,
      values: (): FakeChain => chain,
      onConflictDoNothing: (): FakeChain => chain,
      returning: (): Promise<never[]> => Promise.resolve([]),
      select: (): FakeChain => chain,
      from: (): FakeChain => chain,
      where: (): FakeChain => chain,
      limit: (): Promise<never[]> => Promise.resolve([]),
    };
    const repo = new DrizzleAlgorithmRepository(chain as never);

    await expect(repo.add({ recipe: 'binary.sha256', comparison: Comparison.EXACT })).rejects.toThrow(
      /failed to resolve or create algorithm row/,
    );
  });
});

