    const command = buildApiClientCommand(() => cradle);
    await command.parseAsync(['revoke', '--id', 'nope'], { from: 'user' });

    expect(stderrWrite).toHaveBeenCalled();
    expect(exit).toHaveBeenCalledWith(1);
  });
});

